<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api} from '../services/api';import {usePage} from '../services/usePage';import BoxEditor,{type Box} from '../components/BoxEditor.vue';import Notice from '../components/Notice.vue';import {Save,Trash2,ArrowLeft} from 'lucide-vue-next'
const id=String(useRoute().params.id),image=ref<any>(null),boxes=ref<Box[]>([]),history=ref<any[]>([]),note=ref('');const {error,success,busy,act}=usePage()
async function load(){image.value=(await api.get(`images/${id}/`)).data;boxes.value=image.value.annotations.map((b:Box)=>({...b}));history.value=(await api.get(`images/${id}/history/`)).data}onMounted(()=>act(load))
const save=()=>act(async()=>{await api.patch(`images/${id}/`,{fruit_code:image.value.fruit_code,split:image.value.split,source:image.value.source});await api.post(`images/${id}/annotate/`,{annotations:boxes.value,state:image.value.state,revision:image.value.revision,note:note.value});await load()},'Revisión guardada. Los snapshots anteriores permanecen intactos.')
</script>
<template><RouterLink v-if="image" :to="'/datasets/'+image.dataset" class="mb-4 inline-flex items-center gap-2 text-xs text-slate-500"><ArrowLeft :size="14"/>Volver al dataset</RouterLink><h1 class="heading mb-2">Revisar y anotar</h1><p class="subheading mb-6">Dibuja sobre la imagen para marcar roña. Puedes ajustar cada coordenada o eliminar cajas.</p><Notice :error="error" :success="success"/><div v-if="image" class="grid items-start gap-6 xl:grid-cols-[1.7fr_1fr]"><section class="card"><div class="mb-4 flex justify-between gap-2"><p class="truncate text-sm font-semibold">{{image.name}}</p><span class="text-xs text-slate-400">{{image.width}} × {{image.height}}</span></div><BoxEditor :src="`images/${id}/file/`" :boxes="boxes" :width="image.width" :height="image.height" @change="boxes=$event"/><p class="mt-3 text-xs text-slate-400">Clase única: 0 · rona. Las coordenadas corresponden a los píxeles originales, sin rotación EXIF.</p><div class="mt-4 flex gap-2"><span v-if="image.quality.dark_warning" class="badge !bg-amber-50 !text-amber-700">Posible iluminación baja</span><span v-if="image.quality.blur_warning" class="badge !bg-amber-50 !text-amber-700">Revisar nitidez</span></div></section><form @submit.prevent="save" class="card space-y-4"><h2 class="font-semibold">Validación de la imagen</h2><div><label class="label">Fruto o grupo de partición</label><input v-model="image.fruit_code" class="input" placeholder="Ejemplo: L01-F023"/><p class="mt-1 text-[11px] text-slate-400">Usa el mismo código para fotos del mismo fruto.</p></div><div class="grid grid-cols-2 gap-3"><div><label class="label">Estado</label><select v-model="image.state" class="input"><option value="pending">Pendiente</option><option value="healthy">Sin lesiones</option><option value="lesion">Con roña</option><option value="discarded">Descartada</option></select></div><div><label class="label">Partición</label><select v-model="image.split" class="input"><option value="">Sin asignar</option><option value="train">Train</option><option value="val">Validación</option><option value="test">Prueba</option></select></div></div><div><label class="label">Fuente</label><input v-model="image.source" class="input"/></div><div><label class="label">Cajas · {{boxes.length}}</label><div class="max-h-72 space-y-3 overflow-y-auto"><div v-for="(box,i) in boxes" :key="i" class="rounded-lg bg-slate-50 p-2"><div class="mb-2 flex justify-between"><span class="text-xs font-semibold">{{i+1}} · roña</span><button type="button" @click="boxes.splice(i,1)" :aria-label="'Eliminar caja '+(i+1)" class="text-red-500"><Trash2 :size="14"/></button></div><div class="grid grid-cols-4 gap-1"><label v-for="key in (['x','y','w','h'] as const)" :key="key" class="text-[10px] text-slate-500">{{key}}<input v-model.number="box[key]" class="input !px-1 !py-1 text-xs" type="number" min="0" max="1" step="0.0001"/></label></div></div></div><p v-if="!boxes.length" class="text-xs text-slate-400">Sin cajas. Marca «Sin lesiones» solo después de revisar.</p></div><textarea v-model="note" class="input" placeholder="Observaciones de la revisión"/><button class="btn w-full" :disabled="busy"><Save :size="16"/>Guardar revisión</button><p class="text-[11px] leading-5 text-slate-400">Guardar un estado revisado registra tu usuario como revisor. La referencia debe validarse con una persona competente en identificación de roña.</p></form></div><section v-if="history.length" class="card mt-6"><h2 class="mb-3 font-semibold">Historial de revisiones</h2><p v-for="h in history" :key="h.revision" class="border-t border-slate-100 py-2 text-xs text-slate-500">Rev. {{h.revision}} · {{h.author__username}} · {{h.state}} · {{h.annotations.length}} cajas · {{h.note}}</p></section></template>
